    "caption_es": "Aldea cultural de Gamcheon, en la ladera de una montaña del distrito de Saha-gu. Fue una zona bastante degradada, pero en 2009 se puso en marcha un proyecto de revitalización urbana que llenó sus calles de arte, murales y casas de colores. Hoy es uno de los lugares más visitados de Busan.",
