    "height": 788,
    "caption_ca": "Hahoe és un llogaret tradicional coreà de la dinastia Joseon. Conserva l’arquitectura d’aquell període, tradicions populars i llibres valuosos, i és una part important de la cultura coreana.",
    "caption_es": "Hahoe es una aldea tradicional coreana de la dinastía Joseon. Conserva la arquitectura de aquel período, tradiciones populares y libros valiosos, y es una parte importante de la cultura coreana.",
